import{_ as e,o as r,c as i,a6 as a}from"./chunks/framework.DkN_Sv-a.js";const y=JSON.parse('{"title":"Native driver performance","description":"","frontmatter":{},"headers":[],"relativePath":"background/performance.md","filePath":"background/performance.md","lastUpdated":null}'),d={name:"background/performance.md"};function l(g,t,n,s,h,o){return r(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="Native-driver-performance" tabindex="-1">Native driver performance <a class="header-anchor" href="#Native-driver-performance" aria-label="Permalink to &quot;Native driver performance {#Native-driver-performance}&quot;">​</a></h1><p>Native driver timings use Julia 1.12.6, GeoDataFrames 0.4.3, and the fixtures in <code>test/data</code>. Each result is the median of 20 warmed BenchmarkTools samples. Values compare the ArchGDAL median with the native median; values greater than <code>1.11x</code> make the native backend at least 10% faster.</p><p>CSV uses <code>test_wkt.csv</code>; GeoJSON uses <code>test_points.geojson</code>; Shapefile uses <code>test_points.shp</code>; FlatGeobuf uses <code>countries.fgb</code>; GeoParquet uses <code>example.parquet</code>; and GeoArrow uses <code>example-multipolygon_z.arrow</code>. Write measurements first use the same three-point in-memory table for every backend.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Backend</th><th style="text-align:right;">Operation</th><th style="text-align:right;">Native median (ms)</th><th style="text-align:right;">ArchGDAL median (ms)</th><th style="text-align:right;">ArchGDAL/native</th></tr></thead><tbody><tr><td style="text-align:right;">CSV</td><td style="text-align:right;">read</td><td style="text-align:right;">0.19</td><td style="text-align:right;">0.53</td><td style="text-align:right;">2.85x</td></tr><tr><td style="text-align:right;">GeoJSON</td><td style="text-align:right;">read</td><td style="text-align:right;">0.26</td><td style="text-align:right;">0.54</td><td style="text-align:right;">2.09x</td></tr><tr><td style="text-align:right;">Shapefile</td><td style="text-align:right;">read</td><td style="text-align:right;">0.67</td><td style="text-align:right;">1.18</td><td style="text-align:right;">1.75x</td></tr><tr><td style="text-align:right;">FlatGeobuf</td><td style="text-align:right;">read</td><td style="text-align:right;">11.60</td><td style="text-align:right;">1.00</td><td style="text-align:right;">0.09x</td></tr><tr><td style="text-align:right;">GeoParquet</td><td style="text-align:right;">read</td><td style="text-align:right;">0.73</td><td style="text-align:right;">12.07</td><td style="text-align:right;">16.55x</td></tr><tr><td style="text-align:right;">GeoArrow</td><td style="text-align:right;">read</td><td style="text-align:right;">0.44</td><td style="text-align:right;">0.54</td><td style="text-align:right;">1.21x</td></tr><tr><td style="text-align:right;">CSV</td><td style="text-align:right;">write</td><td style="text-align:right;">0.10</td><td style="text-align:right;">0.20</td><td style="text-align:right;">2.00x</td></tr><tr><td style="text-align:right;">GeoJSON</td><td style="text-align:right;">write</td><td style="text-align:right;">0.11</td><td style="text-align:right;">0.21</td><td style="text-align:right;">2.02x</td></tr><tr><td style="text-align:right;">Shapefile</td><td style="text-align:right;">write</td><td style="text-align:right;">0.42</td><td style="text-align:right;">0.48</td><td style="text-align:right;">1.14x</td></tr><tr><td style="text-align:right;">GeoParquet</td><td style="text-align:right;">write</td><td style="text-align:right;">0.14</td><td style="text-align:right;">0.50</td><td style="text-align:right;">3.49x</td></tr><tr><td style="text-align:right;">GeoArrow</td><td style="text-align:right;">write</td><td style="text-align:right;">0.29</td><td style="text-align:right;">0.30</td><td style="text-align:right;">1.03x</td></tr></tbody></table><h2 id="Write-performance-for-10,000-polygons" tabindex="-1">Write performance for 10,000 polygons <a class="header-anchor" href="#Write-performance-for-10,000-polygons" aria-label="Permalink to &quot;Write performance for 10,000 polygons {#Write-performance-for-10,000-polygons}&quot;">​</a></h2><p>This workload repeats a <code>GeoInterface.Wrappers.MultiPolygon</code> 10,000 times. The polygon is backed by fully materialized nested coordinate vectors, avoiding backend-specific geometry representations. It measures serialization and output costs at a more representative scale.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Backend</th><th style="text-align:right;">Operation</th><th style="text-align:right;">Native median (ms)</th><th style="text-align:right;">ArchGDAL median (ms)</th><th style="text-align:right;">ArchGDAL/native</th></tr></thead><tbody><tr><td style="text-align:right;">CSV</td><td style="text-align:right;">write</td><td style="text-align:right;">783.88</td><td style="text-align:right;">1078.82</td><td style="text-align:right;">1.38x</td></tr><tr><td style="text-align:right;">GeoJSON</td><td style="text-align:right;">write</td><td style="text-align:right;">882.10</td><td style="text-align:right;">10837.51</td><td style="text-align:right;">12.29x</td></tr><tr><td style="text-align:right;">Shapefile</td><td style="text-align:right;">write</td><td style="text-align:right;">768.96</td><td style="text-align:right;">1888.29</td><td style="text-align:right;">2.46x</td></tr><tr><td style="text-align:right;">GeoParquet</td><td style="text-align:right;">write</td><td style="text-align:right;">337.04</td><td style="text-align:right;">1187.14</td><td style="text-align:right;">3.52x</td></tr><tr><td style="text-align:right;">GeoArrow</td><td style="text-align:right;">write</td><td style="text-align:right;">1001.60</td><td style="text-align:right;">1238.35</td><td style="text-align:right;">1.24x</td></tr></tbody></table><h2 id="Read-performance-for-10,000-polygons" tabindex="-1">Read performance for 10,000 polygons <a class="header-anchor" href="#Read-performance-for-10,000-polygons" aria-label="Permalink to &quot;Read performance for 10,000 polygons {#Read-performance-for-10,000-polygons}&quot;">​</a></h2><p>Each format is written once from the same native GeoInterface wrapper, then read repeatedly from that unchanged file. The write step is outside the timed region. CSV uses a <code>WKT</code> geometry column so its native reader parses the geometries.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Backend</th><th style="text-align:right;">Operation</th><th style="text-align:right;">Native median (ms)</th><th style="text-align:right;">ArchGDAL median (ms)</th><th style="text-align:right;">ArchGDAL/native</th></tr></thead><tbody><tr><td style="text-align:right;">CSV</td><td style="text-align:right;">read</td><td style="text-align:right;">143.94</td><td style="text-align:right;">2432.79</td><td style="text-align:right;">16.90x</td></tr><tr><td style="text-align:right;">GeoJSON</td><td style="text-align:right;">read</td><td style="text-align:right;">384.71</td><td style="text-align:right;">2971.83</td><td style="text-align:right;">7.72x</td></tr><tr><td style="text-align:right;">Shapefile</td><td style="text-align:right;">read</td><td style="text-align:right;">40.59</td><td style="text-align:right;">130.61</td><td style="text-align:right;">3.22x</td></tr><tr><td style="text-align:right;">GeoParquet</td><td style="text-align:right;">read</td><td style="text-align:right;">26.11</td><td style="text-align:right;">98.00</td><td style="text-align:right;">3.75x</td></tr><tr><td style="text-align:right;">GeoArrow</td><td style="text-align:right;">read</td><td style="text-align:right;">0.76</td><td style="text-align:right;">95.06</td><td style="text-align:right;">125.63x</td></tr></tbody></table>',10)])])}const c=e(d,[["render",l]]);export{y as __pageData,c as default};
